 const feedback=state.homeAnswer?`<div class="specimen-feedback ${state.homeAnswer==='safe'?'good':'caution'}" role="status"><b>${tr(state.homeAnswer==='safe'?'Good instinct':'Notice the pressure',state.homeAnswer==='safe'?'To‘g‘ri yo‘nalish':'Shoshilishga e’tibor bering')}</b><p>${e(t(state.homeAnswer==='safe'?'heroFeedbackGood':'heroFeedbackBad'))}</p></div>`:'';
 const journey=[
  {n:'01',icon:'◉',title:tr('Understand','Tushunib oling'),desc:tr('5 short interactive lessons about emotions, evidence, privacy and safety.','Hissiyot, dalil, maxfiylik va xavfsizlik haqida 5 ta interaktiv dars.'),counter:`${doneLabs()}/5`,to:doneLabs()<5?`lab-${Math.max(0,nextLab)}`:'lab-0',done:doneLabs()===5},
  {n:'02',icon:'↗',title:tr('Try it yourself','Amalda sinab ko‘ring'),desc:tr('Make decisions in 6 realistic, safe scenarios.','6 ta hayotiy va xavfsiz vaziyatda mustaqil qaror qiling.'),counter:`${doneMissions()}/6`,to:'missions',done:doneMissions()===6},
  {n:'03',icon:'✓',title:tr('Check your judgment','O‘zingizni sinang'),desc:tr('20 new questions to test how you think, not what you memorized.','Yodlashni emas, fikrlashni baholaydigan 20 ta yangi savol.'),counter:state.submitted?'✓':`${doneTest()}/20`,to:state.submitted?'results':'test',done:state.submitted}
 ];
 const labIcons=['♡','⌕','◎','▣','↗'];
